import re, os, shutil

telop = "\u672c\u65e5\u306e\u4e00\u54c1"
store = "\u3059\u3055\u3073\u6e6f \u6cb3\u539f\u753a\u4e09\u6761\u5e97"

old = "src/Root.tsx"
if os.path.exists(old):
    t = open(old, encoding="utf-8").read()
    m = re.search(r'telop:\s*"((?:[^"\\]|\\.)*)"', t)
    if m and m.group(1).strip():
        telop = m.group(1)
    m = re.search(r'storeName:\s*"((?:[^"\\]|\\.)*)"', t)
    if m and m.group(1).strip():
        store = m.group(1)

for f in ("src/SushiStory.tsx", "src/Root.tsx"):
    if os.path.exists(f) and not os.path.exists(f + ".bak"):
        shutil.copy(f, f + ".bak")

open("src/SushiStory.tsx", "w", encoding="utf-8").write('import {\n  AbsoluteFill,\n  Audio,\n  Img,\n  Sequence,\n  staticFile,\n  getStaticFiles,\n  interpolate,\n  useCurrentFrame,\n  useVideoConfig,\n} from "remotion";\nimport { loadFont } from "@remotion/google-fonts/YujiSyuku";\n\nconst { fontFamily: brushFont } = loadFont();\n\nconst BG = "#1a0f0a";\nconst ACCENT = "#d4a574";\nconst SLIDE = 110;\nconst FADE = 20;\n\nconst getPhotos = (): string[] =>\n  getStaticFiles()\n    .filter(\n      (f) =>\n        f.name.startsWith("photos/") && /\\.(jpe?g|png|webp)$/i.test(f.name)\n    )\n    .sort((a, b) => a.name.localeCompare(b.name))\n    .map((f) => f.src);\n\nconst Slide: React.FC<{ src: string }> = ({ src }) => {\n  const frame = useCurrentFrame();\n  const opacity = interpolate(\n    frame,\n    [0, FADE, SLIDE - FADE, SLIDE],\n    [0, 1, 1, 0],\n    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }\n  );\n  const scale = interpolate(frame, [0, SLIDE], [1.05, 1.18], {\n    extrapolateRight: "clamp",\n  });\n  const drift = interpolate(frame, [0, SLIDE], [-14, 14]);\n  return (\n    <AbsoluteFill style={{ opacity }}>\n      <AbsoluteFill>\n        <Img\n          src={src}\n          style={{\n            width: "100%",\n            height: "100%",\n            objectFit: "cover",\n            filter: "blur(30px) brightness(0.4)",\n            transform: `scale(${1.2 * scale})`,\n          }}\n        />\n      </AbsoluteFill>\n      <AbsoluteFill\n        style={{\n          background:\n            "linear-gradient(180deg, rgba(26,15,10,0.30) 0%, rgba(26,15,10,0.10) 30%, rgba(26,15,10,0.10) 60%, rgba(26,15,10,0.85) 100%)",\n        }}\n      />\n      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>\n        <div\n          style={{\n            boxShadow: "0 20px 60px rgba(0,0,0,0.6)",\n            borderRadius: 14,\n            overflow: "hidden",\n            transform: `translateX(${drift}px) scale(${scale})`,\n          }}\n        >\n          <Img\n            src={src}\n            style={{\n              width: 1080 * 0.84,\n              height: "auto",\n              maxHeight: 1920 * 0.56,\n              objectFit: "cover",\n              display: "block",\n            }}\n          />\n        </div>\n      </AbsoluteFill>\n    </AbsoluteFill>\n  );\n};\n\nexport const SushiStory: React.FC<{ telop?: string; storeName?: string }> = ({\n  telop = "",\n  storeName = "",\n}) => {\n  const frame = useCurrentFrame();\n  const { durationInFrames } = useVideoConfig();\n  const photos = getPhotos();\n\n  const globalOpacity = interpolate(\n    frame,\n    [0, 12, durationInFrames - 15, durationInFrames],\n    [0, 1, 1, 0],\n    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }\n  );\n  const storeOpacity = interpolate(frame, [0, 28], [0, 1], {\n    extrapolateRight: "clamp",\n  });\n  const telopOpacity = interpolate(\n    frame,\n    [10, 40, durationInFrames - 30, durationInFrames],\n    [0, 1, 1, 0],\n    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }\n  );\n  const telopY = interpolate(frame, [10, 40], [26, 0], {\n    extrapolateRight: "clamp",\n  });\n\n  return (\n    <AbsoluteFill style={{ backgroundColor: BG, opacity: globalOpacity }}>\n      <Audio\n        src={staticFile("bgm.mp3")}\n        volume={(f) =>\n          interpolate(\n            f,\n            [0, 30, durationInFrames - 45, durationInFrames],\n            [0, 0.5, 0.5, 0],\n            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }\n          )\n        }\n      />\n\n      {photos.map((src, i) => (\n        <Sequence key={i} from={i * (SLIDE - FADE)} durationInFrames={SLIDE}>\n          <Slide src={src} />\n        </Sequence>\n      ))}\n\n      <div\n        style={{\n          position: "absolute",\n          top: 92,\n          width: "100%",\n          textAlign: "center",\n          opacity: storeOpacity,\n          color: ACCENT,\n          fontFamily: brushFont,\n          fontSize: 38,\n          letterSpacing: 8,\n          textShadow: "0 2px 12px rgba(0,0,0,0.85)",\n        }}\n      >\n        {storeName}\n      </div>\n\n      <div\n        style={{\n          position: "absolute",\n          bottom: 150,\n          width: "100%",\n          display: "flex",\n          flexDirection: "column",\n          alignItems: "center",\n          opacity: telopOpacity,\n          transform: `translateY(${telopY}px)`,\n        }}\n      >\n        <div\n          style={{\n            width: 64,\n            height: 1,\n            background: `linear-gradient(90deg, transparent, ${ACCENT}, transparent)`,\n            marginBottom: 28,\n          }}\n        />\n        <div\n          style={{\n            color: "#fff",\n            fontFamily: brushFont,\n            fontSize: 54,\n            letterSpacing: 4,\n            textAlign: "center",\n            padding: "0 60px",\n            lineHeight: 1.4,\n            textShadow:\n              "0 2px 20px rgba(0,0,0,0.85), 0 0 40px rgba(212,165,116,0.3)",\n          }}\n        >\n          {telop}\n        </div>\n      </div>\n    </AbsoluteFill>\n  );\n};\n')
open("src/Root.tsx", "w", encoding="utf-8").write(
    'import { Composition, getStaticFiles } from "remotion";\nimport { SushiStory } from "./SushiStory";\n\nconst FPS = 30;\nconst SLIDE = 110;\nconst FADE = 20;\n\nconst countPhotos = (): number =>\n  getStaticFiles().filter(\n    (f) => f.name.startsWith("photos/") && /\\.(jpe?g|png|webp)$/i.test(f.name)\n  ).length;\n\nexport const RemotionRoot: React.FC = () => {\n  return (\n    <>\n      <Composition\n        id="SushiStory"\n        component={SushiStory}\n        fps={FPS}\n        width={1080}\n        height={1920}\n        durationInFrames={180}\n        defaultProps={{\n          telop: "__TELOP__",\n          storeName: "__STORE__",\n        }}\n        calculateMetadata={() => {\n          const n = Math.max(countPhotos(), 1);\n          return { durationInFrames: n * (SLIDE - FADE) + FADE };\n        }}\n      />\n    </>\n  );\n};\n'.replace("__TELOP__", telop).replace("__STORE__", store)
)
print("OK: \u8907\u6570\u753b\u50cf\u5bfe\u5fdc\u306b\u66f4\u65b0\u3057\u307e\u3057\u305f\u3002")
print("   store =", store)
print("   telop =", telop)
